17	/* audio_capture.c — Audio capture via board aw-alsa-lib (snd_vela_pcm).
18	 *
19	 * 2026-08-11 上板修复（P55+，mic demo -5）：原实现走 openvela
20	 * media_recorder 框架，但 R528 gemini-s1 固件未编译 media server
21	 * （CONFIG_LIB_FFMPEG / CONFIG_LIB_PFW 均未启用），
22	 * media_recorder_open() 恒返回 NULL → audio_capture_open 失败 → -EIO。
23	 * 改为直接调用板级 aw-alsa-lib（snd_vela_pcm_*），与 luncher_dm 音乐
24	 * 播放（dm_sound）同源、已在上板验证可用的 PCM 路径。 */
25	
26	#include "voice/audio_capture.h"
27	#include "agent_config.h"
28	
29	#include "pcm.h"     /* aw-alsa-lib: snd_vela_pcm_* */
30	#include "control.h" /* aw-alsa-lib: snd_ctl_set（MIC 通路使能） */
31	
32	#include <errno.h>
33	#include <stdio.h>
34	#include <stdlib.h>
35	#include <string.h>
36	#include <syslog.h>
37	#include <unistd.h>
38	
39	static const char* TAG = "audio_cap";
40	
41	/* Audio gain multiplier to compensate for multi-channel DMIC mixing.
42	 * When board configures 6 DMIC channels but only 1 has a physical mic,
43	 * the mono mix dilutes the signal by ~6x. Set gain to compensate.
44	 * Configurable via CONFIG_AI_AGENT_AUDIO_CAPTURE_GAIN in Kconfig. */
45	#ifdef CONFIG_AI_AGENT_AUDIO_CAPTURE_GAIN
46	#define AGENT_AUDIO_CAPTURE_GAIN CONFIG_AI_AGENT_AUDIO_CAPTURE_GAIN
47	#else
48	#define AGENT_AUDIO_CAPTURE_GAIN 6
49	#endif
50	
51	/* 板级 PCM 卡名：与 luncher_dm dm_sound_open 一致（CONFIG_AW_AUDIO_CODEC=y） */
52	#define AGENT_CAPTURE_CARD "hw:audiocodec"
53	
54	/* 捕获 buffer 参考 arecord：period 1024 / buffer 4096 帧 */
55	#define AGENT_CAPTURE_PERIOD 1024
56	#define AGENT_CAPTURE_BUFFER 4096
57	
58	struct audio_capture {
59	    snd_pcm_t* pcm;
60	    unsigned int sample_rate;
61	    unsigned int channels;
62	    unsigned int bits_per_sample;
63	};
64	
65	audio_capture_t* audio_capture_open(const char* dev_path,
66	    unsigned int sample_rate, unsigned int channels,
67	    unsigned int bits_per_sample)
68	{
69	    (void)dev_path; /* aw-alsa-lib 按卡名路由，无需设备路径 */
70	
71	    /* 2026-08-11 P56+ 修复：集成 MIC（MICIN1P/MICIN1N + MBIAS → ADC1）。
72	     * codec 默认 MIC_PGA_EN（MIC1 input switch）关闭 → sunxi_get_adc_ch()
73	     * 返回 -1 → capture hw_params 报 "only support 1~3 channel" -22。
74	     * 先经 snd_ctl 打开 ADC1 MIC 通路 + 增益（参考 HAL aloop 测试写法）。 */
75	    snd_ctl_set("audiocodec", "MIC1 gain volume", 19);
76	    snd_ctl_set("audiocodec", "MIC1 input switch", 1);
77	    snd_ctl_set("audiocodec", "MIC2 input switch", 0);
78	    snd_ctl_set("audiocodec", "MIC3 input switch", 0);
79	
80	    snd_pcm_t* handle = NULL;
81	    snd_pcm_hw_params_t* params = NULL;
82	    snd_pcm_uframes_t period = AGENT_CAPTURE_PERIOD;
83	    snd_pcm_uframes_t buffer = AGENT_CAPTURE_BUFFER;
84	    int ret;
85	
86	    ret = snd_vela_pcm_open(&handle, AGENT_CAPTURE_CARD,
87	        SND_VELA_PCM_STREAM_CAPTURE, 0);
88	    if (ret < 0) {
89	        syslog(LOG_ERR, "[%s] snd_vela_pcm_open(%s, CAPTURE) fail %d\n",
90	            TAG, AGENT_CAPTURE_CARD, ret);
91	        return NULL;
92	    }
93	
94	    snd_vela_pcm_hw_params_malloc(&params);
95	    ret = snd_vela_pcm_hw_params_any(handle, params);
96	    if (ret < 0) {
97	        syslog(LOG_ERR, "[%s] hw_params_any fail %d\n", TAG, ret);
98	        goto err;
99	    }
100	
101	    snd_vela_pcm_hw_params_set_access(handle, params,
102	        SND_PCM_ACCESS_RW_INTERLEAVED);
103	    snd_vela_pcm_hw_params_set_format(handle, params, SND_PCM_FORMAT_S16_LE);
104	    snd_vela_pcm_hw_params_set_channels(handle, params, channels);
105	    snd_vela_pcm_hw_params_set_rate(handle, params, sample_rate, 0);
106	    snd_vela_pcm_hw_params_set_period_size(handle, params, period, 0);
107	    snd_vela_pcm_hw_params_set_buffer_size(handle, params, buffer);
108	
109	    ret = snd_vela_pcm_hw_params(handle, params);
110	    snd_vela_pcm_hw_params_free(params);
111	    params = NULL;
112	    if (ret < 0) {
113	        syslog(LOG_ERR, "[%s] hw_params fail %d\n", TAG, ret);
114	        goto err;
115	    }
116	
117	    /* SW params：捕获 start_threshold=1（有数据即自动启动），
118	     * 参考 arecord set_param 的 CAPTURE 分支。 */
119	    {
120	        snd_pcm_sw_params_t* sw;
121	        snd_pcm_sw_params_alloca(&sw);
122	        snd_vela_pcm_sw_params_current(handle, sw);
123	        snd_vela_pcm_sw_params_set_start_threshold(handle, sw, 1);
124	        snd_vela_pcm_sw_params_set_stop_threshold(handle, sw, buffer);
