178	int audio_capture_read(audio_capture_t* cap, void* buf, size_t len)
179	{
180	    if (!cap || !cap->pcm || !buf || len == 0) {
181	        return -EINVAL;
182	    }
183	
184	    int frame_bytes = (int)cap->channels * ((int)cap->bits_per_sample / 8);
185	    snd_pcm_uframes_t frames = (snd_pcm_uframes_t)(len / (size_t)frame_bytes);
186	    snd_pcm_sframes_t n;
187	    int retries = 0;
188	
189	    if (frames == 0) {
190	        return -EINVAL;
191	    }
192	
193	    /* EAGAIN 短暂重试；EPIPE（xrun）prepare 恢复后重读 */
194	    for (;;) {
195	        n = snd_vela_pcm_readi(cap->pcm, buf, frames);
196	        if (n == -EAGAIN && retries < 10) {
197	            usleep(10 * 1000);
198	            retries++;
199	            continue;
200	        } else if (n == -EPIPE) {
201	            syslog(LOG_WARNING, "[%s] xrun, recovering\n", TAG);
202	            snd_vela_pcm_prepare(cap->pcm);
203	            if (retries < 10) {
204	                retries++;
205	                continue;
206	            }
207	        }
208	
209	        break;
210	    }
211	
212	    if (n < 0) {
213	        syslog(LOG_ERR, "[%s] readi fail %ld\n", TAG, (long)n);
214	        return (int)n;
215	    }
216	
217	    size_t got = (size_t)n * (size_t)frame_bytes;
218	
219	    /* Apply gain to compensate for multi-channel DMIC mixing.
220	     * When 6 DMIC channels are configured but only 1 has a physical mic,
221	     * the mono downmix dilutes the signal. Amplify to restore level. */
222	#if AGENT_AUDIO_CAPTURE_GAIN > 1
223	    if (got > 0) {
224	        int16_t* samples = (int16_t*)buf;
225	        int sample_count = (int)got / 2;
226	
227	        for (int i = 0; i < sample_count; i++) {
228	            int32_t amplified = (int32_t)samples[i] * AGENT_AUDIO_CAPTURE_GAIN;
229	
230	            /* Clamp to 16-bit range to prevent overflow */
231	            if (amplified > 32767) {
232	                amplified = 32767;
233	            } else if (amplified < -32768) {
234	                amplified = -32768;
235	            }
236	
237	            samples[i] = (int16_t)amplified;
238	        }
239	    }
240	#endif
241	
242	    return (int)got;
243	}
