205	/* Extract "content":"..." value from a JSON response */
206	static void extract_content(const char *json, char *out, int outcap)
207	{
208	    const char *p = strstr(json, "\"content\"");
209	    if (!p)
210	        {
211	            out[0] = '\0';
212	            return;
213	        }
214	    p = strchr(p, ':');
215	    if (!p)
216	        {
217	            out[0] = '\0';
218	            return;
219	        }
220	    p = strchr(p, '"');
221	    if (!p)
222	        {
223	            out[0] = '\0';
224	            return;
225	        }
226	    p++;
227	    int o = 0;
228	    while (*p && *p != '"' && o < outcap - 1)
229	        {
230	            if (*p == '\\' && (p[1] == 'n' || p[1] == 't' || p[1] == '"'))
231	                {
232	                    out[o++] = (p[1] == 'n') ? '\n' : (p[1] == 't') ? '\t' : '"';
233	                    p += 2;
234	                }
235	            else
236	                {
237	                    out[o++] = *p++;
238	                }
239	        }
240	    out[o] = '\0';
241	}
