64	static int arecord(const char *card_name, snd_pcm_format_t format, unsigned int rate,
65			   unsigned int channels, const void *data, unsigned int datalen)
66	{
67		int ret = 0;
68		snd_pcm_t *handle;
69		int mode = 0;
70		snd_pcm_uframes_t period_frames = 1024, buffer_frames = 4096;
71	
72		syslog(LOG_INFO,"dump args:\n");
73		syslog(LOG_INFO,"card:      %s\n", card_name);
74		syslog(LOG_INFO,"format:    %u\n", format);
75		syslog(LOG_INFO,"rate:      %u\n", rate);
76		syslog(LOG_INFO,"channels:  %u\n", channels);
77		syslog(LOG_INFO,"data:      %p\n", data);
78		syslog(LOG_INFO,"datalen:   %u\n", datalen);
79	
80		/* open card */
81		ret = snd_vela_pcm_open(&handle, card_name, SND_VELA_PCM_STREAM_CAPTURE, mode);
82		if (ret < 0) {
83			syslog(LOG_ERR,"audio open error:%d\n", ret);
84			return -1;
85		}
86	
87		ret = set_param(handle, format, rate, channels, period_frames, buffer_frames);
88		if (ret < 0)
89			goto err1;
90		do {
91			syslog(LOG_INFO,"pcm_read start...\n");
92			ret = pcm_read(handle, data,
93				snd_vela_pcm_bytes_to_frames(handle, datalen),
94				snd_vela_pcm_frames_to_bytes(handle, 1));
95			if (ret < 0) {
96				syslog(LOG_ERR,"capture error:%d\n", ret);
97				goto err1;
98			}
99		} while (g_capture_loop_enable);
100	
101		ret = snd_vela_pcm_drain(handle);
102		if (ret < 0)
103			syslog(LOG_ERR,"stop failed!, return %d\n", ret);
104	
105	err1:
106		/* close card */
107		ret = snd_vela_pcm_close(handle);
108		if (ret < 0) {
109			syslog(LOG_ERR,"audio close error:%d\n", ret);
110			return ret;
111		}
112	
113		return ret;
114	}
