210			}
211		}
212		while ((rest > 0 || g_capture_loop_enable) && !mgr->in_aborting) {
213			long f = mgr->period_size;
214			if (rest <= chunk_bytes && !g_capture_loop_enable)
215				c = rest;
216			else
217				c = chunk_bytes;
218			f = pcm_read(mgr->handle, audiobuf, f, frame_bytes);
219			if (f < 0) {
220				syslog(LOG_ERR,"pcm read error, return %ld\n", f);
221				break;
222			}
223			if (save_fs && fd > 0) {
224				ret = write(fd, audiobuf, c);
225				if (ret != c) {
226					syslog(LOG_ERR,"write audiobuf to wav file failed, return %d\n", ret);
227					goto err;
228				}
229			}
230	
231			if (rest > 0)
