242		ret = snd_vela_pcm_close(mgr->handle);
243		if (ret < 0) {
244			syslog(LOG_ERR,"audio close error:%d\n", ret);
245			return ret;
246		}
247	
248		if (save_fs && fd > 0 && ret == 0) {
249			resize_wav(&header, written);
250			lseek(fd, 0, SEEK_SET);
251			write(fd, &header, sizeof(header));
252		}
253	
254		if (save_fs) {
255			if (fd > 0)
256				close(fd);
257		}
258		if (audiobuf)
259			free(audiobuf);
260	
261		return ret;
262	}
